/bin/zsh -lc "python -c 'import pandas as pd,numpy as np,json,math
x=pd.read_csv(\"respondents.csv\"); w=x.wt_final; allr=pd.Series(True,index=x.index)
def base(v,e=allr):
 v=v&e
 return dict(eligible_n=int(e.sum()),eligible_w=float(w[e].sum()),valid_n=int(v.sum()),valid_w=float(w[v].sum()),ess=float(w[v].sum()**2/(w[v]**2).sum()))
def tab(c,codes,e=allr):
 v=x[c].isin(codes)&e; r=base(v,e); r[\"pct\"]={str(k):float(100*w[v&x[c].eq(k)].sum()/w[v].sum()) for k in codes}; r[\"missing\"]={str(k):int((e&x[c].eq(k)).sum()) for k in [97,98,99]}; r[\"blank\"]=int((e&x[c].isna()).sum()); return r
out={\"full\":base(allr),\"ordinal\":{c:tab(c,range(1,6)) for c in x if c.startswith(\"att_\")},\"states\":{c:tab(c,[0,1]) for c in [\"need_budget\",\"need_effort\",\"need_waste\"]}}
for block,cols in [(\"needs\",[c for c in x if c.startswith(\"support_\")]),(\"barriers\",[c for c in x if c.startswith(\"barrier_\")])]:
 v=x[block+\"_block_status\"].eq(1); r=base(v); r[\"pct\"]={c:float(100*w[v&x[c].eq(1)].sum()/w[v].sum()) for c in cols}; r[\"none_pct\"]=float(100*w[v&x[cols].eq(0).all(axis=1)].sum()/w[v].sum()); r[\"missing\"]={str(k):int(x[block+\"_block_status\"].eq(k).sum()) for k in [97,98]}; out[block]=r
v=x[[\"need_budget\",\"need_effort\",\"need_waste\"]].isin([0,1]).all(axis=1); out[\"overlap\"]=base(v); out[\"overlap\"][\"pct\"]={\"\".join(map(str,k)):float(w[v&(x.need_budget==k[0])&(x.need_effort==k[1])&(x.need_waste==k[2])].sum()/w[v].sum()*100) for k in [(a,b,c) for a in [0,1] for b in [0,1] for c in [0,1]]}
out[\"tools\"]=tab(\"planning_tool_28d\",[0,1,2,3]); e=x.planning_tool_28d.isin([1,2,3]); out[\"satisfaction\"]=tab(\"tool_satisfaction_5\",range(1,6),e); out[\"sharing\"]=tab(\"shared_list_use_28d\",[0,1],e)
out[\"tests\"]={}
spec=[(\"NEED_EFFORT_TOPUPS\",\"need_effort\",\"unplanned_topups_7d\"),(\"NEED_EFFORT_PLANNING\",\"need_effort\",\"meal_plan_days_7d\"),(\"NEED_BUDGET_OVERSPEND\",\"need_budget\",\"over_budget_4w\"),(\"NEED_WASTE_DISCARD\",\"need_waste\",\"waste_days_7d\"),(\"CHILDREN_TOPUPS\",\"children_u16\",\"unplanned_topups_7d\"),(\"CHILDREN_PLANNING\",\"children_u16\",\"meal_plan_days_7d\")]
for id,g,y in spec:
 valid=x[g].isin([0,1])&x[y].isin([0,1] if y==\"over_budget_4w\" else range(8)); a=np.zeros(len(x)); means=[]; r={}
 for k in [0,1]:
  e=x[g].eq(k); v=e&valid; mu=np.average(x.loc[v,y],weights=w[v]); means.append(mu); r[str(k)]=dict(base(v,e),mean=float(mu),outcome_dk_n=int((e&x[y].eq(97)).sum()),outcome_refusal_n=int((e&x[y].eq(98)).sum())); a+=np.where(v,w*(x[y]-mu)/w[v].sum(),0)*(1 if k else -1)
 variance=0
 for _,idx in x.groupby([\"age_band\",\"children_u16\"]).groups.items():
  z=a[idx]; variance+=len(z)/(len(z)-1)*((z-z.mean())**2).sum()
 scale=100 if y==\"over_budget_4w\" else 1; d=(means[1]-means[0])*scale; se=math.sqrt(variance)*scale; r.update(diff=d,se=se,ci=[d-1.959963984540054*se,d+1.959963984540054*se],p=math.erfc(abs(d/se)/math.sqrt(2))); out[\"tests\"][id]=r
for ids in [[s[0] for s in spec[:4]],[s[0] for s in spec[4:]]]:
 order=sorted(ids,key=lambda i:out[\"tests\"][i][\"p\"]); prev=0
 for j,i in enumerate(order):
  prev=max(prev,min(1,(len(ids)-j)*out[\"tests\"][i][\"p\"])); out[\"tests\"][i][\"holm_p\"]=prev
v=x.att_plan_ahead_5.between(1,5)&x.att_spontaneous_5.between(1,5)&x.meal_plan_days_7d.between(0,7); z=(x.loc[v,\"att_plan_ahead_5\"]+6-x.loc[v,\"att_spontaneous_5\"])/2; y=x.loc[v,\"meal_plan_days_7d\"]; zc=z-np.average(z,weights=w[v]); yc=y-np.average(y,weights=w[v]); out[\"orientation\"]=dict(base(v),r=float((w[v]*zc*yc).sum()/np.sqrt((w[v]*zc**2).sum()*(w[v]*yc**2).sum())))
out[\"small_paid_65\"]=tab(\"tool_satisfaction_5\",range(1,6),x.age_band.eq(4)&x.planning_tool_28d.eq(3))
print(json.dumps(out,indent=2))'"

