for c in ["tool_satisfaction_5","shared_list_use_28d"]:out[c]={"unasked_nonuser":int((x[c].isna()&x.planning_tool_28d.eq(0)).sum()),"unasked_unknown_screener":int((x[c].isna()&x.planning_tool_28d.isin([97,98])).sum()),"blank_current_user":int((x[c].isna()&x.planning_tool_28d.isin([1,2,3])).sum())}
