 cols=[c for c in x if c.startswith(prefix)]; status=x[block+"_block_status"]; out[block+"_invalid_answered_rows"]=int((status.eq(1)&~x[cols].isin([0,1]).all(axis=1)).sum());out[block+"_missing_mismatches"]=int((status.isin([97,98])&~x[cols].eq(status,axis=0).all(axis=1)).sum())
print(json.dumps(out))'"'"

